"use strict";
// Loads its parts with a computed specifier (R1.2): a Node island.
const { createRequire } = require("node:module");
const load = createRequire(__filename);
const { Counter } = load(["./lib", "counter"].join("/"));

exports.makeCounter = (start) => new Counter(start);
exports.Counter = Counter;
// A files map: native callers build their own with the same interface.
exports.countFiles = (files) => Object.keys(files).length;
exports.describeFile = (file) => `${file.mode}:${file.data.toString("utf8")}`;
exports.blob = (text) => ({ mode: 420, data: Buffer.from(text) });
exports.text = (text) => ({ mode: 384, data: text });
// Takes options built from spread and method members.
exports.render = (opts) => `${opts.name}/${opts.retries}/${opts.format(opts.name)}`;
// Settles a promise with an Error the caller inspects in .catch.
exports.failLater = (message) => Promise.reject(Object.assign(new Error(message), { code: "EFAIL" }));
